function tmQuery(dataApi,table,opts){opts=opts||{};var top=opts.top||5000;var sel=opts.select&&opts.select.length?opts.select:null;var web=tmWeb();var firstErr=null;function viaXrm(useSel){var parts=[];if(opts.filter)parts.push('$filter='+tmEnc(opts.filter));if(useSel)parts.push('$select='+useSel.join(','));if(opts.orderBy)parts.push('$orderby='+opts.orderBy);var q='?'+parts.join('&');var rows=[];var pages=0;function page(query){return tmTimeout(function(){return web.retrieveMultipleRecords(table,query,Math.min(top,5000));},tmT('Read of {t}',{t:table})).then(function(res){var ents=res&&res.entities?res.entities:[];rows=rows.concat(ents);pages++;var next=res&&res.nextLink;if(next&&rows.length<top&&pages<TM_PAGE_CAP){var i=next.indexOf('?');return page(i>=0?next.slice(i):next);}return rows.slice(0,top);});}return page(q);}function viaApi(useSel){var q={pageSize:Math.min(top,500)};if(opts.filter)q.filter=opts.filter;if(opts.orderBy)q.orderBy=opts.orderBy;if(useSel)q.select=useSel;return tmTimeout(function(){return dataApi.queryTable(table,q);},tmT('Read of {t}',{t:table})).then(function(pg){var rows=pg&&pg.rows?Array.prototype.slice.call(pg.rows):null;if(!rows)throw new Error(tmT('No rows came back from {t}',{t:table}));var n=0;function more(p){if(p&&p.hasMoreRows&&typeof p.loadMoreRows==='function'&&rows.length<top&&n<200){n++;return tmTimeout(function(){return p.loadMoreRows();},tmT('Read of {t}',{t:table})).then(function(nx){rows=rows.concat(nx&&nx.rows?Array.prototype.slice.call(nx.rows):[]);return more(nx);});}return rows.slice(0,top);}return more(pg);});}function attempt(useSel){if(web){return viaXrm(useSel).then(function(rows){return{rows:rows,via:'Xrm.WebApi'};},function(e){firstErr=tmErrText(e);if(dataApi&&dataApi.queryTable)return viaApi(useSel).then(function(rows){return{rows:rows,via:'dataApi'};},function(e2){return{rows:null,err:firstErr||tmErrText(e2)};});return{rows:null,err:firstErr};});}if(dataApi&&dataApi.queryTable)return viaApi(useSel).then(function(rows){return{rows:rows,via:'dataApi'};},function(e){return{rows:null,err:tmErrText(e)};});return Promise.resolve({rows:null,err:tmT('This page has no Dataverse connection (no Xrm.WebApi and no dataApi).'),kind:'nohost'});}return attempt(sel).then(function(r){if(r.rows||!sel||tmErrKind(r.err)!=='column'||opts.strictSelect){if(!r.rows&&!r.kind)r.kind=tmErrKind(r.err);return r;}// A listed column the table lacks fails the whole read: read again with every column.
return attempt(null).then(function(r2){r2.droppedSelect=true;if(!r2.rows&&!r2.kind)r2.kind=tmErrKind(r2.err);return r2;});});}// Reads the first table name in the list that exists. Resolves { table, rows, err, kind, via }.
function tmQueryFirst(dataApi,names,opts){var i=0;var last=null;function next(){if(i>=names.length)return Promise.resolve(last||{rows:null,err:'No table name to try',kind:'missing'});var t=names[i++];return tmQuery(dataApi,t,opts).then(function(r){r.table=t;if(r.rows)return r;if(!last||last.kind==='missing')last=r;if(r.kind==='missing')return next();return r;// denied or unknown: do not hide it behind a later name
});}return next();}// Which of the names is the real table: one tiny read each.
function tmProbe(dataApi,names){var i=0;var res={table:null,state:'missing',why:''};function next(){if(i>=names.length)return Promise.resolve(res);var t=names[i++];return tmQuery(dataApi,t,{select:[tmIdCol(t)],top:1,strictSelect:true}).then(function(r){if(r.rows)return{table:t,state:'found',why:''};var k=r.kind||tmErrKind(r.err);if(k==='column')return{table:t,state:'found',why:'The id column '+tmIdCol(t)+' was not found, so its name differs: '+r.err};if(k==='denied')return{table:t,state:'denied',why:r.err};if(k==='nohost')return{table:null,state:'nohost',why:r.err};if(k==='unknown'){res={table:null,state:'unknown',why:r.err};return next();}if(res.state==='missing')res.why=r.err;return next();});}return next();}// Columns of a found table: one tiny read per column.
function tmProbeCols(dataApi,table,cols){var out={};var chain=Promise.resolve();cols.forEach(function(c){chain=chain.then(function(){return tmQuery(dataApi,table,{select:[c],top:1,strictSelect:true}).then(function(r){out[c]=r.rows?'found':tmErrKind(r.err)==='column'?'missing':'unknown';});});});return chain.then(function(){return out;});}function tmIdOf(res){var id=typeof res==='string'?res:res&&(res.id||res.entityId||res.recordId);return id?tmCleanId(id):null;}// Writes: Xrm.WebApi first, else dataApi. Null when there is no way to write.
function tmWriter(dataApi){var x=tmXrm();var web=x&&x.WebApi;if(web&&web.createRecord&&web.updateRecord){return{create:function(t,body){return tmTimeout(function(){return web.createRecord(t,body);},tmT('Save to {t}',{t:t})).then(tmIdOf);},update:function(t,id,body){return tmTimeout(function(){return web.updateRecord(t,id,body);},tmT('Save to {t}',{t:t}));},remove:function(t,id){return tmTimeout(function(){return web.deleteRecord(t,id);},tmT('Delete from {t}',{t:t}));}};}if(dataApi&&dataApi.createRow&&dataApi.updateRow){return{create:function(t,body){return tmTimeout(function(){return dataApi.createRow(t,body);},tmT('Save to {t}',{t:t})).then(tmIdOf);},update:function(t,id,body){return tmTimeout(function(){return dataApi.updateRow(t,id,body);},tmT('Save to {t}',{t:t}));},remove:function(t,id){return dataApi.deleteRow?tmTimeout(function(){return dataApi.deleteRow(t,id);},tmT('Delete from {t}',{t:t})):Promise.reject(new Error(tmT('Delete is not available here')));}};}return null;}// Create, or update when an id is known; a write that names a missing column says which one.
function tmSave(dataApi,table,id,body){var w=tmWriter(dataApi);if(!w)return Promise.reject(new Error(tmT('This page cannot write to Dataverse here.')));var p=id?w.update(table,id,body).then(function(){return id;}):w.create(table,body);return p.catch(function(e){var m=tmErrText(e);if(tmErrKind(m)==='column')throw new Error(tmT('A column is missing in {t}: {err}',{t:table,err:m}));throw new Error(m);});}// The _p_ Plan json column can be smaller than a plan (Copilot often makes it 2,000 characters). A plan that does not fit is
// saved in parts: the row with the key, then key#2, key#3 ... with status 'saved 1/3' on the first row; the reader joins them.
function tmUserName(){var x=tmXrm();try{var gc=x&&x.Utility&&x.Utility.getGlobalContext&&x.Utility.getGlobalContext();var u=gc&&gc.userSettings;if(u&&u.userName)return String(u.userName);}catch(e){/* not in host */}return'';}// Who is signed in (the Microsoft account Power Apps runs as). Never rejects: { id, name, first, email, source, warn }.
// The Power Apps sign-in details give the id and name; the systemuser row adds the first name and email when it can be read.
function tmReadUser(props){var out={id:'',name:'',first:'',email:'',source:'',warn:''};var x=tmXrm();try{var gc=x&&x.Utility&&x.Utility.getGlobalContext?x.Utility.getGlobalContext():null;var us=gc?gc.userSettings:null;if(!us&&props&&props.context)us=props.context.userSettings;if(us){out.id=tmCleanId(us.userId||'');out.name=tmTrim(us.userName||'');out.source='Power Apps sign-in';}}catch(e){out.warn=tmErrText(e);}if(out.name.indexOf('@')>0){out.email=out.name.toLowerCase();out.name='';}var web=x&&x.WebApi;if(!out.id||!web||typeof web.retrieveRecord!=='function'){out.first=tmFirstName(out.name);return Promise.resolve(out);}return tmTimeout(function(){return web.retrieveRecord('systemuser',out.id,'?$select=fullname,firstname,internalemailaddress,domainname');},tmT('Reading your user record')).then(function(r){r=r||{};out.name=tmTrim(r.fullname)||out.name;out.first=tmTrim(r.firstname)||tmFirstName(out.name);out.email=String(r.internalemailaddress||r.domainname||out.email||'').trim().toLowerCase();out.source='Power Apps sign-in and your user record';return out;},function(e){out.first=tmFirstName(out.name);out.warn=tmErrText(e);return out;});}// "Smith, Alex" -> Alex; "Alex Smith" -> Alex.
function tmFirstName(n){var s=tmTrim(n);if(!s)return'';if(s.indexOf(',')>0)return tmTrim(s.split(',')[1]).split(' ')[0]||s;return s.split(' ')[0];}// Developer tools (Setup, Data) open for the accounts on the list. An empty list = not locked yet (first unlock offers to lock it).
function tmIsDev(user,devUsers){var list=Array.isArray(devUsers)?devUsers:[];if(!list.length)return true;if(!user)return false;return list.some(function(d){return!!d&&(d.id&&user.id&&tmCleanId(d.id)===user.id||d.email&&user.email&&String(d.email).toLowerCase()===user.email);});}// Pure planning functions: no React, no Dataverse. Each takes rows that were really read and returns what the screens draw.
